-- 신조어 후보 9건 승격 (2026-09-06, 운영자 승인). draft_payload 그대로, 임의 수정 없음.
-- 얼렁뚱땡이 / 갑통알 / 김풍스럽다 / 동결건조 / 기대컨 / 톤망진창 / 기카노보 / 꺄르 / 할렐야루
--
-- 검수 메모에서 넘어온 유보 사항(초안이 확정 서술을 피한 지점 — 그대로 유지):
--  * 김풍스럽다 — 뜻은 세 출처 일치하나 어느 출처도 유래를 밝히지 않아 어원 미기재.
--  * 톤망진창 — 뜻 명시 출처가 카드뉴스 1개뿐. 조어법(톤+엉망진창)은 형태 분석이며 출처 없음.
--    기존어 '톤그로'와 동의어일 가능성이 남아 있는데 '톤그로'는 아직 DB에 없다 —
--    나중에 등록하면서 같은 말로 판명되면 CLAUDE.md 표제어 규칙대로 alias 통합 대상.
--  * 갑통알 — 부산일보 2019년 기사가 최초 사용처를 밝히지 않아 등장 시점만 근사치.
--  * 기카노보 — 창작자 귀속이 출처마다 상충(허니제이 창작 vs 질문)이라 특정하지 않음.
--  * 꺄르 — 의성어 '꺄르르' 축약설과 '야르' 파생설을 병기.
--  * 할렐야루 — 유래 두 설(할렐루야+야르 / 교회 팻말 실수) 병기, 교회 실명은 넣지 않음.
--
-- 관련 단어 중 아직 DB에 없는 항목(상세 화면에서 비활성 칩으로만 표시되고 링크는 안 걸림):
--  * 동결건조 → '가슴에 국밥 쏟음' (검수 대기 상태, 승격되면 자동으로 연결됨)
--  * 톤망진창 → '톤그로' (미등록)
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words (id, word, romanization, category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('273', '얼렁뚱땡이', 'Eol-leong-ttung-ttaeng-i', 'new-slang', '결심만 하고 흐지부지 넘기는 사람', '{"de": "Jemand, der Vorsätze fasst und sie stillschweigend versanden lässt", "en": "Someone who makes resolutions and quietly lets them slide", "es": "Quien se propone cosas y las deja pasar sin más", "ja": "決心だけして、うやむやに終わらせてしまう人", "vi": "Người chỉ quyết tâm rồi lặng lẽ bỏ dở"}'::jsonb, '[얼렁뚱땡이]', '[{"type": "명사", "examples": [{"de": "Nach drei Tagen schon wieder aufgegeben. Typisch ich, die Vorsatz-Verdrückerin.", "es": "Otra vez lo dejé a los tres días. Yo, la reina de las promesas incumplidas.", "ja": "今回も三日坊主。私ってほんとオルロンットゥンテンイ。", "vi": "Lại bỏ cuộc sau ba ngày. Đúng chất mình - chuyên gia hứa suông.", "eng": "Three days and I quit again. Classic me, the great resolution-dodger.", "kor": "이번에도 작심삼일이네. 나란 얼렁뚱땡이."}, {"de": "Fitnessstudio angemeldet, zweimal hingegangen. Vorsatz-Verdrückerin, bestätigt.", "es": "Me apunté al gimnasio y fui dos veces. Promesa incumplida certificada.", "ja": "ジムに登録して二回しか行ってない。オルロンットゥンテンイ認定。", "vi": "Đăng ký phòng gym rồi đi được hai buổi. Công nhận mình hứa suông thật.", "eng": "Signed up for the gym and went twice. Certified resolution-dodger.", "kor": "헬스장 등록만 하고 두 번 갔어. 얼렁뚱땡이 인정."}], "definition": "다이어트나 새해 계획처럼 마음만 먹고 제대로 실행하지 않은 채 어물쩍 넘기는 사람. 실패를 심각하게 자책하기보다 가볍게 웃어넘기는 자조적·애교 섞인 말이라, 남을 지적할 때보다 자기를 부를 때 훨씬 많이 쓴다.", "definition_i18n": {"de": "Jemand, der sich etwas vornimmt - eine Diät, einen Neujahrsvorsatz - und es dann still versanden lässt. Das Wort hat keinen Stachel: Es ist eine sanfte, fast liebevolle Art, über das eigene Scheitern zu lachen, statt sich zu geißeln - daher sagt man es viel öfter über sich selbst als über andere.", "en": "Someone who sets a goal - a diet, a New Year plan - and then just lets it quietly slide. The word carries no real sting: it is a soft, almost affectionate way of laughing at your own failure rather than beating yourself up, so it is used about oneself far more than about others.", "es": "Alguien que se propone algo -una dieta, un plan de Año Nuevo- y luego lo deja pasar sin más. La palabra no hiere: es una forma suave, casi cariñosa, de reírse del propio fracaso en vez de castigarse, así que se usa mucho más sobre uno mismo que sobre otros.", "ja": "ダイエットや新年の計画のように、心に決めただけで実行せずうやむやに済ませてしまう人。失敗を深刻に責めるより軽く笑い飛ばす自嘲的で愛嬌のある言葉なので、他人を指すより自分を呼ぶときにずっとよく使う。", "vi": "Người đặt mục tiêu - giảm cân, kế hoạch năm mới - rồi lẳng lặng bỏ dở. Từ này không hề gắt: đó là cách nhẹ nhàng, gần như đáng yêu, để tự cười vào thất bại của mình thay vì tự trách, nên hay dùng cho bản thân hơn là cho người khác."}}]'::jsonb, '부사 얼렁뚱땅(일을 대충 어물쩍 넘기는 모양)에 사람을 뜻하는 접미사 -이를 붙여 만든 말. 2026년 스레드·인스타그램의 신조어 모음과 다이어트 계정을 중심으로 퍼졌고, 최초로 쓴 사람이나 계정은 확인되지 않았다.', '{"de": "Gebildet aus dem Adverb eolleongttungttang (etwas schludrig durchwinken) plus -i, dem Suffix, das aus einer Art eine Person macht. Verbreitet 2026 über Slang-Sammlungen und Diät-Accounts auf Threads und Instagram; der Erstverwender ist unbestätigt.", "en": "Built from the adverb eolleongttungttang (fudging something through carelessly) plus -i, the suffix that turns a manner into a person. It spread through 2026 slang round-ups and diet accounts on Threads and Instagram; the first user is unverified.", "es": "Formada a partir del adverbio eolleongttungttang (salir del paso a lo chapucero) más -i, el sufijo que convierte un modo en una persona. Se difundió en 2026 por recopilaciones de jerga y cuentas de dieta en Threads e Instagram; se desconoce quién lo usó primero.", "ja": "副詞オルロンットゥンタン(物事をいい加減にうやむやと済ませる様子)に、人を表す接尾辞「-이」を付けて作った語。2026年にThreadsやInstagramの新造語まとめとダイエット系アカウントを中心に広まった。最初に使った人は未確認。", "vi": "Ghép từ trạng từ eolleongttungttang (làm qua loa cho xong) với hậu tố -i biến cách thức thành người. Lan rộng năm 2026 qua các bài tổng hợp từ mới và tài khoản giảm cân trên Threads, Instagram; chưa rõ ai dùng đầu tiên."}'::jsonb, '작심삼일한 자신을 웃어넘길 때 쓴다. 친한 사이에서 상대를 놀릴 때도 쓰지만 기본은 자조다.', '{"de": "Um über die eigenen Drei-Tage-Vorsätze zu lachen; man kann damit enge Freunde necken, doch Selbstironie ist der Normalfall.", "en": "Used to laugh off your own three-day resolutions; you can tease a close friend with it, but self-mockery is the default.", "es": "Se usa para reírse de los propios propósitos que duran tres días; puedes picar a un amigo cercano, pero lo normal es la autoburla.", "ja": "三日坊主に終わった自分を笑い飛ばすときに使う。親しい相手をからかうのにも使えるが、基本は自嘲。", "vi": "Dùng để cười trừ chuyện mình bỏ cuộc sau ba ngày; có thể trêu bạn thân, nhưng chủ yếu là tự giễu."}'::jsonb, array['갓생','스불재','현타'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Resolution-dodger (all plans, no follow-through)"}, {"lang": "🇯🇵 JA", "text": "決心だけしてうやむやにする人"}, {"lang": "🇨🇳 ZH", "text": "只下决心却敷衍了事的人"}, {"lang": "🇻🇳 VI", "text": "Người hứa suông rồi bỏ dở"}, {"lang": "🇪🇸 ES", "text": "Quien solo se propone y nunca cumple"}, {"lang": "🇩🇪 DE", "text": "Vorsatz-Verdrücker"}]'::jsonb),
('274', '갑통알', 'Gap-Tong-Al', 'new-slang', '통장 잔고 보고 알바를 결심하게 되는 순간', '{"de": "Der Moment, in dem dein Kontostand nach einem Nebenjob schreit", "en": "That moment your bank balance makes you consider a side job", "es": "El momento en que tu saldo te empuja a buscar un trabajillo", "ja": "通帳残高を見てバイトを決意する瞬間", "vi": "Khoảnh khắc nhìn số dư rồi quyết định đi làm thêm"}'::jsonb, '[갑통알]', '[{"type": "명사", "examples": [{"de": "Hab die Kartenabbuchung gesehen und war sofort im Nebenjob-Modus …", "es": "Vi el cargo de la tarjeta y me entró el modo ''necesito un curro''…", "ja": "カードの引き落とし見て、いきなりバイト決意モードになった…", "vi": "Nhìn tiền thẻ bị trừ xong tự dưng thấy phải đi làm thêm…", "eng": "Saw the card bill come out of my account and instantly went ''guess I need a side job''.", "kor": "카드값 빠져나간 거 보고 갑통알 왔다…"}, {"de": "Gehalt kam vor zwei Tagen und ich bin schon wieder im Nebenjob-Modus.", "es": "Cobré hace dos días y ya estoy en modo ''busco curro''.", "ja": "給料入って2日なのにもうバイト決意モード。", "vi": "Mới lãnh lương hai ngày mà đã thấy cần đi làm thêm rồi.", "eng": "Payday was two days ago and I''m already in side-job panic mode.", "kor": "월급 들어온 지 이틀 됐는데 벌써 갑통알이야."}], "definition": "''갑자기 통장을 보니 알바(아르바이트)해야겠다''의 줄임말. 잔고를 확인한 순간 정신이 번쩍 들어 부업이라도 해야겠다는 생각이 드는 상황을 가리키는 자조적인 말이다.", "definition_i18n": {"de": "Kurz für ''hab plötzlich aufs Konto geschaut — ich brauche einen Nebenjob''. Selbstironischer Name für den Schreck beim Blick auf den Kontostand.", "en": "Short for ''suddenly looked at my bank account — I need a part-time job''. A self-deprecating name for the jolt you get from checking your balance and realising you need extra income.", "es": "Abreviatura de ''de repente miré mi cuenta y me toca buscar un curro''. Nombre autoirónico para el susto de ver el saldo y darte cuenta de que necesitas más ingresos.", "ja": "「急に通帳を見たらバイトしなきゃ」の略。残高を確認した瞬間、我に返って副業でもしなきゃと思う状況を指す自嘲的な言葉。", "vi": "Viết tắt của ''tự dưng nhìn tài khoản, chắc phải đi làm thêm''. Cách nói tự giễu về cú giật mình khi xem số dư và nhận ra mình cần kiếm thêm."}}]'::jsonb, '''갑자기 / 통장 / 알바''의 첫 글자를 딴 줄임말이다. 2019년 전후 20~30대 사이에서 퍼졌고, 고물가·고금리 국면마다 언론이 청년층의 경제 사정을 보여주는 ''웃픈'' 신조어로 반복해 소개했다. 최초 사용처는 어느 출처에도 나오지 않는다.', '{"de": "Kurzform aus den Anfangssilben von 갑자기 (plötzlich) / 통장 (Konto) / 알바 (Nebenjob). Verbreitete sich um 2019 unter 20- bis 30-Jährigen; Medien zitieren es immer wieder als bittersüßes Bild der Finanzlage junger Leute. Der Erstgebrauch ist nirgends belegt.", "en": "An acronym-style clip of 갑자기(suddenly) / 통장(bank account) / 알바(part-time job). It spread among Koreans in their 20s-30s around 2019 and has been repeatedly cited in the press as a bittersweet marker of young people''s finances. No source identifies where it was first used.", "es": "Recorte con las primeras sílabas de 갑자기 (de repente) / 통장 (cuenta) / 알바 (trabajillo). Se extendió entre veinteañeros y treintañeros hacia 2019 y la prensa lo repite como retrato agridulce de las finanzas juveniles. Ninguna fuente señala su primer uso.", "ja": "「急に/通帳/バイト」の頭文字を取った略語。2019年前後に20~30代の間で広まり、物価高・高金利のたびに若年層の家計を映す「笑えて悲しい」新造語としてメディアに繰り返し紹介された。最初の使用元は不明。", "vi": "Ghép âm đầu của 갑자기 (đột nhiên) / 통장 (tài khoản) / 알바 (làm thêm). Lan rộng trong giới 20-30 tuổi quanh năm 2019, được báo chí nhắc lại như hình ảnh vừa buồn cười vừa chua chát về tài chính của người trẻ. Không nguồn nào nêu lần dùng đầu tiên."}'::jsonb, '월급날 직후나 카드 결제일에 자조적으로 쓴다. 정말 아르바이트를 구한다는 뜻보다 ''돈이 없다''는 과장 표현으로 쓰는 경우가 훨씬 많다.', '{"de": "Selbstironisch direkt nach dem Zahltag oder am Tag der Kartenabbuchung. Meist heißt es schlicht ''ich bin pleite'', nicht dass jemand wirklich einen Job sucht.", "en": "Used self-deprecatingly right after payday or on card-payment day. Far more often it just means ''I''m broke'' than that anyone is actually job-hunting.", "es": "Se usa con autoironía justo después de cobrar o el día del cargo de la tarjeta. Casi siempre significa ''estoy sin blanca'', no que vayas a buscar trabajo de verdad.", "ja": "給料日直後やカードの引き落とし日に自嘲的に使う。本当にバイトを探すというより「お金がない」の誇張表現として使うことが圧倒的に多い。", "vi": "Dùng để tự giễu ngay sau ngày lãnh lương hoặc ngày trừ tiền thẻ. Phần lớn chỉ có nghĩa ''hết tiền rồi'' chứ không phải thật sự đi tìm việc."}'::jsonb, array['월급 루팡','워라밸','현타'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Broke-check panic (time for a side job)"}, {"lang": "🇯🇵 JA", "text": "残高見てバイト決意"}, {"lang": "🇨🇳 ZH", "text": "看到余额想去打工"}, {"lang": "🇻🇳 VI", "text": "Nhìn số dư là muốn đi làm thêm"}, {"lang": "🇪🇸 ES", "text": "Susto de saldo (toca buscar curro)"}, {"lang": "🇩🇪 DE", "text": "Kontostand-Schock (Nebenjob nötig)"}]'::jsonb),
('275', '김풍스럽다', 'Gim-Pung-Seu-Reop-Da', 'new-slang', '과정은 불안한데 결과는 잘 나오는', '{"de": "Wackliger Prozess, erstaunlich gutes Ergebnis", "en": "Sketchy process, surprisingly great result", "es": "Proceso dudoso, resultado sorprendentemente bueno", "ja": "過程は不安なのに結果は上出来", "vi": "Quá trình lộn xộn mà kết quả lại ngon"}'::jsonb, '[김풍스럽따]', '[{"type": "형용사", "examples": [{"de": "Ohne Rezept gemacht und es schmeckt? Total nach dem Motto: chaotisch, aber es klappt.", "es": "¿Ni miré la receta y está buenísimo? Puro caos que sale bien.", "ja": "レシピ見ないで作ったのにおいしい?完全に「過程は雑、結果は上出来」ってやつ。", "vi": "Chẳng thèm xem công thức mà ngon nhỉ? Đúng kiểu làm bừa mà ra ngon.", "eng": "Didn''t even look at a recipe and it''s good? Classic sketchy-but-it-works.", "kor": "레시피 안 보고 했는데 맛있네? 완전 김풍스럽다."}, {"de": "Sah aus, als hätte er nichts für den Vortrag vorbereitet — und trotzdem wurde es gut.", "es": "Parecía que no había preparado nada la presentación y al final salió genial.", "ja": "発表の準備を全然してないように見えたのに、結果はちゃんと良かったね。", "vi": "Trông như chẳng chuẩn bị gì cho bài thuyết trình mà kết quả lại ổn ghê.", "eng": "Looked like they''d prepped nothing for the talk, and yet it came out great anyway.", "kor": "발표 준비 하나도 안 한 것 같더니 결과는 김풍스럽게 잘 나왔네."}], "definition": "만드는 과정은 대충이고 불안해 보이는데 결과물은 의외로 훌륭할 때 쓰는 말. 요리처럼 눈앞에서 과정이 보이는 일에 특히 잘 어울린다.", "definition_i18n": {"de": "Wenn der Ablauf schlampig und riskant wirkt, das Ergebnis aber überraschend gut wird. Passt besonders dort, wo man den Prozess sieht — vor allem beim Kochen.", "en": "Used when the process looks slapdash and precarious but the finished thing turns out unexpectedly good. It fits best where you can watch the process happen — cooking above all.", "es": "Se usa cuando el proceso parece chapucero e inestable pero el resultado sale inesperadamente bien. Encaja sobre todo cuando ves el proceso en directo, como al cocinar.", "ja": "作る過程は雑で不安そうなのに、出来上がりは意外と見事なときに使う。料理のように過程が目に見える作業に特にしっくりくる。", "vi": "Dùng khi cách làm trông cẩu thả, bấp bênh mà thành phẩm lại ngon bất ngờ. Hợp nhất với những việc thấy được quá trình, nhất là nấu ăn."}}]'::jsonb, '어원은 확정되지 않았다. 2026년 1월 언론 카드뉴스와 매거진이 ''2026년 신조어'' 목록에 같은 뜻으로 실었으나, 어느 출처도 말이 어디서 나왔는지 설명하지 않는다. 사람 이름에 ''-스럽다''를 붙여 성질을 나타내는 한국어의 흔한 조어 방식을 따른 것으로만 확인된다.', '{"de": "Die Herkunft ist ungeklärt. Im Januar 2026 führten koreanische Card-News und Magazine das Wort mit genau dieser Bedeutung unter den Neuschöpfungen des Jahres, doch keine Quelle erklärt, woher es stammt. Belegt ist nur die Form: ein Personenname plus das koreanische Suffix -스럽다, das aus einem Namen eine Eigenschaft macht.", "en": "The etymology is unsettled. Korean press card-news pieces and magazines listed it in January 2026 among the year''s new coinages with this same meaning, but none of them explains where the word came from. All that is confirmed is the form: a personal name plus the Korean suffix -스럽다, which turns a name into a quality.", "es": "La etimología no está establecida. En enero de 2026, cardnews y revistas coreanas lo incluyeron entre los neologismos del año con este mismo significado, pero ninguna explica de dónde viene. Solo se confirma la forma: un nombre propio más el sufijo coreano -스럽다, que convierte un nombre en una cualidad.", "ja": "語源は確定していない。2026年1月に韓国のカードニュースや雑誌が「2026年の新造語」として同じ意味で紹介したが、どの出典も由来を説明していない。確認できるのは形だけで、人名に性質を表す接尾辞「-스럽다」を付ける韓国語の一般的な造語法に従っている。", "vi": "Nguồn gốc chưa được xác định. Tháng 1/2026, các bài cardnews và tạp chí Hàn liệt kê nó trong danh sách từ mới của năm với đúng nghĩa này, nhưng không nguồn nào giải thích từ đâu ra. Chỉ xác nhận được về mặt hình thức: tên riêng ghép hậu tố -스럽다, biến tên thành tính chất."}'::jsonb, '요리나 작업의 결과물이 예상 밖으로 잘 나왔을 때 칭찬 반, 놀림 반으로 쓴다. 2026년 초에 소개된 말이라 아직 널리 통하지는 않을 수 있다.', '{"de": "Halb Lob, halb Neckerei für ein Gericht oder Werk, das besser wurde, als der Prozess vermuten ließ. Es tauchte erst Anfang 2026 auf — nicht jeder kennt es schon.", "en": "Half compliment, half tease, aimed at a dish or a piece of work that came out better than the process suggested. It only surfaced in early 2026, so not everyone will recognise it yet.", "es": "Mitad elogio, mitad burla, para un plato o un trabajo que salió mejor de lo que el proceso prometía. Apareció a principios de 2026, así que puede que aún no todos lo entiendan.", "ja": "料理や作業の出来が予想以上に良かったときに、半分ほめ・半分からかいで使う。2026年初めに紹介されたばかりの言葉なので、まだ通じない相手もいる。", "vi": "Nửa khen nửa trêu, dành cho món ăn hay sản phẩm ra tốt hơn cả quá trình làm. Mới xuất hiện đầu năm 2026 nên chưa chắc ai cũng hiểu."}'::jsonb, array['갓벽','이왜진'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Messy process, great result"}, {"lang": "🇯🇵 JA", "text": "過程は雑、結果は上出来"}, {"lang": "🇨🇳 ZH", "text": "过程随便，结果很棒"}, {"lang": "🇻🇳 VI", "text": "Làm bừa mà ra ngon"}, {"lang": "🇪🇸 ES", "text": "Caótico pero sale bien"}, {"lang": "🇩🇪 DE", "text": "Chaotisch gemacht, top geworden"}]'::jsonb),
('276', '동결건조', 'Dong-Gyeol-Geon-Jo', 'new-slang', '소중한 사람을 지금 모습 그대로 간직하고 싶다는 마음', '{"de": "Der Wunsch, dass ein geliebter Mensch für immer so bleibt", "en": "Wishing someone precious could stay exactly as they are forever", "es": "Querer que alguien querido se quede tal como está para siempre", "ja": "大切な人に今のままでいてほしいという気持ち", "vi": "Ước người mình thương mãi giữ nguyên như bây giờ"}'::jsonb, '[동결건조]', '[{"type": "명사·동사", "examples": [{"de": "Ich wünschte, Mama würde nie älter … am liebsten würde ich sie gefriertrocknen.", "es": "Ojalá mamá no envejeciera… de verdad quiero liofilizarla.", "ja": "お母さんに年を取ってほしくない…本当に凍結乾燥したい。", "vi": "Ước gì mẹ đừng già đi… thật sự muốn sấy đông mẹ luôn.", "eng": "I wish Mom would never get older… I honestly want to freeze-dry her.", "kor": "엄마 안 늙었으면 좋겠어… 진짜 동결건조 시키고 싶다."}, {"de": "Mein Hund ist gerade auf dem Niedlichkeits-Höhepunkt — gefriertrocknen möglich?", "es": "Mi perro está en su punto máximo de ternura, ¿lo puedo liofilizar?", "ja": "うちの犬、今が一番かわいいんだけど凍結乾燥できない?", "vi": "Cún nhà mình giờ đáng yêu nhất, sấy đông được không nhỉ?", "eng": "My dog is at peak cuteness right now — can I freeze-dry him?", "kor": "우리 강아지 지금이 제일 귀여운데 동결건조 가능?"}], "definition": "동결건조 식품이 신선함을 그대로 유지하듯, 소중한 사람(주로 엄마)이 늙거나 변하지 않고 지금 모습 그대로 곁에 있어 주길 바라는 마음을 귀엽게 비유한 말. ‘○○ 동결건조하고 싶다’ 꼴로 쓴다.", "definition_i18n": {"de": "So wie gefriergetrocknete Lebensmittel frisch bleiben, drückt es liebevoll den Wunsch aus, dass ein geliebter Mensch — meist die Mutter — nie altert. Gebraucht als „Ich will ○○ gefriertrocknen“.", "en": "Just as freeze-dried food keeps its freshness, this is a cute way of wishing someone precious — usually your mom — would never age or change. Used as “I want to freeze-dry ○○.”", "es": "Igual que un alimento liofilizado conserva su frescura, expresa con ternura el deseo de que alguien querido —normalmente tu madre— no envejezca ni cambie. Se usa como “quiero liofilizar a ○○”.", "ja": "フリーズドライ食品が鮮度を保つように、大切な人(主に母)が年を取らず今のままでいてほしいという気持ちをかわいく例えた言葉。「○○を凍結乾燥したい」の形で使う。", "vi": "Như thực phẩm sấy đông giữ nguyên độ tươi, đây là cách nói dễ thương rằng mong người thân (thường là mẹ) đừng già đi hay đổi thay. Dùng dạng “muốn sấy đông ○○”."}}]'::jsonb, '2025년 9월 X(구 트위터)에 올라온 “엄마 안늙었음좋겠음.. 엄마동결건조시키고싶음”이라는 글에서 퍼졌다는 설명이 여러 출처에서 공통으로 나온다. 다만 원 게시자 계정은 출처마다 표기가 달라 확정하지 않는다. 이후 스레드·인스타그램으로 번지며 20대 자녀 세대를 중심으로 정착했다.', '{"de": "Mehrere Quellen führen es auf einen Post vom September 2025 auf X zurück: „Ich will nicht, dass Mama altert … ich will Mama gefriertrocknen.“ Der Ursprungsaccount wird unterschiedlich angegeben und bleibt daher offen. Danach verbreitete es sich über Threads und Instagram unter Zwanzigjährigen.", "en": "Multiple sources trace it to a September 2025 post on X reading “I wish Mom would not age… I want to freeze-dry Mom.” The original account is cited differently across sources, so it is left unstated. It then spread to Threads and Instagram among people in their twenties.", "es": "Varias fuentes lo remontan a una publicación de septiembre de 2025 en X: “Ojalá mamá no envejeciera… quiero liofilizar a mamá”. La cuenta original varía según la fuente, así que no se afirma. Luego se extendió a Threads e Instagram entre los veinteañeros.", "ja": "2025年9月にX(旧Twitter)へ投稿された「お母さんに年を取ってほしくない…お母さんを凍結乾燥したい」という文から広まった、と複数の出典が一致。ただし投稿主のアカウント名は出典ごとに異なるため明記しない。その後Threads・Instagramへ広がり20代を中心に定着。", "vi": "Nhiều nguồn truy về một bài đăng tháng 9/2025 trên X: “Ước mẹ đừng già… muốn sấy đông mẹ”. Tài khoản gốc được ghi khác nhau giữa các nguồn nên không khẳng định. Sau đó lan sang Threads và Instagram trong giới ngoài 20."}'::jsonb, '부모, 반려동물, 최애 등 ‘변하지 않았으면 하는 대상’에게 쓴다. 직접 말하기 쑥스러운 애정을 농담처럼 돌려 전하는 표현이라 진지한 자리보다 SNS·메신저에서 자주 보인다.', '{"de": "Für Eltern, Haustiere oder das Bias — alle, die sich nicht verändern sollen. Es transportiert Zuneigung, die man schwer direkt ausspricht, und taucht daher eher in Social Media und DMs auf.", "en": "Used for parents, pets, or your bias — anyone you do not want to change. It carries affection that is embarrassing to say straight, so it shows up on social media and in DMs more than in serious conversation.", "es": "Se usa con padres, mascotas o tu bias: cualquiera que no quieras que cambie. Vehicula un cariño que da vergüenza decir de frente, así que aparece más en redes y mensajes que en conversaciones serias.", "ja": "親、ペット、推しなど「変わってほしくない相手」に使う。面と向かって言いにくい愛情を冗談めかして伝える表現なので、SNSやDMでよく見かける。", "vi": "Dùng cho bố mẹ, thú cưng hay idol yêu thích — ai mà bạn không muốn đổi thay. Nó chở tình cảm ngại nói thẳng nên hay thấy trên mạng xã hội và tin nhắn hơn là lúc nói chuyện nghiêm túc."}'::jsonb, array['최애','심쿵','가슴에 국밥 쏟음'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Freeze-dry (keep someone as they are)"}, {"lang": "🇯🇵 JA", "text": "凍結乾燥(今のままでいて)"}, {"lang": "🇨🇳 ZH", "text": "冻干(希望永远保持现在的样子)"}, {"lang": "🇻🇳 VI", "text": "Sấy đông (giữ nguyên như bây giờ)"}, {"lang": "🇪🇸 ES", "text": "Liofilizar (que no cambie nunca)"}, {"lang": "🇩🇪 DE", "text": "Gefriertrocknen (so bleiben, wie man ist)"}]'::jsonb),
('277', '기대컨', 'Gi-Dae-Keon', 'new-slang', '미리 기대치를 낮춰 실망을 줄이는 것', '{"de": "Die Erwartungen vorab senken, um Enttäuschung zu dämpfen", "en": "Lowering your expectations in advance to soften disappointment", "es": "Bajar las expectativas de antemano para no decepcionarse", "ja": "あらかじめ期待値を下げてがっかりを減らすこと", "vi": "Hạ kỳ vọng trước để đỡ thất vọng"}'::jsonb, '[기대컨]', '[{"type": "명사", "examples": [{"de": "Ich hab die Prüfung wohl verhauen, also bitte Erwartungen runter.", "es": "Creo que suspendí el examen, así que baja tus expectativas.", "ja": "今回の試験ダメだったっぽいから、期待値下げといて。", "vi": "Kỳ thi này mình toang rồi, hạ kỳ vọng giùm nhé.", "eng": "I think I bombed this exam, so please dial your expectations down.", "kor": "나 이번 시험 망한 것 같으니까 기대컨 좀 해줘."}, {"de": "Beim neuen Album Erwartungen runter — der Teaser war schon alles haha.", "es": "Con el nuevo álbum toca bajar expectativas: el teaser era todo jaja.", "ja": "新アルバムは期待値下げ必須。ティザーが全部だったわw", "vi": "Album mới phải hạ kỳ vọng thôi, teaser là hết rồi haha.", "eng": "You have to expectation-control the new album — the teaser was the whole thing lol.", "kor": "새 앨범 기대컨 필수임, 티저가 다였음 ㅋㅋ"}], "definition": "‘기대 컨트롤’의 줄임말. 무언가에 큰 기대를 걸었다가 실망하지 않도록 스스로, 혹은 상대에게 부탁해 기대치를 미리 낮추는 것.", "definition_i18n": {"de": "Kurz für „Erwartungskontrolle“: die eigenen oder fremden Erwartungen vorab senken, damit die Enttäuschung kleiner ausfällt.", "en": "Short for “expectation control”: lowering your own (or asking someone to lower their) expectations ahead of time so the letdown is smaller.", "es": "Abreviatura de “control de expectativas”: bajar de antemano las expectativas propias o ajenas para que la decepción sea menor.", "ja": "「期待コントロール」の略。がっかりしないよう、自分や相手の期待値をあらかじめ下げておくこと。", "vi": "Viết tắt của “kiểm soát kỳ vọng”: hạ trước kỳ vọng của mình hoặc của người khác để bớt hụt hẫng."}}]'::jsonb, '‘기대’와 영어 control의 줄임말 ‘컨’이 결합한 말. 스트리머·크리에이터가 콘텐츠 공개 전 시청자에게 “기대컨 하라”고 말하던 것이 게임 커뮤니티로 퍼졌다는 설명이 가장 널리 알려져 있으나, 최초 사용자와 시점은 확정되지 않았다.', '{"de": "Eine Mischung aus 기대 (Erwartung) und „con“, gekürzt von control. Am verbreitetsten ist die Erklärung, Streamer hätten vor Veröffentlichungen zur „Erwartungskontrolle“ aufgerufen, doch der genaue Ursprung ist ungeklärt.", "en": "A blend of 기대 (expectation) and “con,” clipped from control. The most common account is that streamers told viewers to “expectation-control” before a reveal and it spread through gaming communities, but the first user and date are unconfirmed.", "es": "Mezcla de 기대 (expectativa) y “con”, de control. La versión más difundida es que los streamers pedían “controlar expectativas” antes de un estreno y se extendió por las comunidades de videojuegos, pero el origen exacto no está confirmado.", "ja": "「期待」と英語controlの略「コン」の合成。配信者が公開前に「期待値下げて」と言ったのがゲームコミュニティに広がった、という説明が最も広まっているが、初出は未確定。", "vi": "Ghép 기대 (kỳ vọng) với “con” rút từ control. Cách giải thích phổ biến nhất là các streamer bảo người xem “hạ kỳ vọng” trước khi ra mắt rồi lan sang cộng đồng game, nhưng nguồn gốc chính xác chưa được xác nhận."}'::jsonb, '콘텐츠 공개, 시험 결과, 소개팅 등 결과가 나오기 전에 “기대컨 해”라고 미리 못을 박는다. 겸손을 가장한 방어이자 가벼운 농담으로 쓰인다.', '{"de": "Man sagt es vor einer Enthüllung, Note oder einem Blind Date: „Erwartungen runter.“ Vorbeugende Bescheidenheit und ein kleiner Scherz.", "en": "Said before a reveal, exam result, or blind date — “expectation-control, please.” It works as pre-emptive modesty and a light joke.", "es": "Se dice antes de un estreno, una nota o una cita a ciegas: “controla expectativas”. Es una defensa preventiva con aire de modestia y un chiste ligero.", "ja": "公開前・結果発表前・合コン前などに「期待値下げといて」と先に言う。謙遜を装った予防線であり、軽い冗談。", "vi": "Nói trước khi công bố, trả điểm hay đi xem mắt: “hạ kỳ vọng nhé”. Vừa là rào trước kiểu khiêm tốn, vừa là đùa nhẹ."}'::jsonb, array['떡밥','억텐','에바'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Expectation control / lower your hopes"}, {"lang": "🇯🇵 JA", "text": "期待値コントロール"}, {"lang": "🇨🇳 ZH", "text": "降低期待值"}, {"lang": "🇻🇳 VI", "text": "Hạ kỳ vọng trước"}, {"lang": "🇪🇸 ES", "text": "Control de expectativas"}, {"lang": "🇩🇪 DE", "text": "Erwartungskontrolle"}]'::jsonb),
('278', '톤망진창', 'Ton-Mang-Jin-Chang', 'new-slang', '피부톤과 안 어울려 엉망이 된 화장이나 옷차림', '{"de": "Make-up oder Outfit, dessen Töne mit dem Teint kollidieren", "en": "Makeup or an outfit whose tones clash with your complexion", "es": "Maquillaje o ropa cuyos tonos chocan con tu piel", "ja": "肌のトーンに合わずぐちゃぐちゃになったメイクや服装", "vi": "Trang điểm hay trang phục lệch tông với da"}'::jsonb, '[톤망진창]', '[{"type": "명사", "examples": [{"de": "Den Lippenstift hab ich im Ladenlicht gekauft — aufgetragen ist es ein Ton-Desaster.", "es": "Compré este labial con la luz de la tienda y puesto es un desastre de tono.", "ja": "店の照明で買ったリップ、塗ってみたらトーン崩壊だった。", "vi": "Mua thỏi son dưới ánh đèn cửa hàng, tô lên mới thấy lệch tông kinh khủng.", "eng": "I bought this lipstick under store lighting and on me it is a total tone disaster.", "kor": "조명 보고 산 립인데 발라보니까 톤망진창이야."}, {"de": "Ohne die eigene Personal Color zu kennen, ist das Ton-Desaster garantiert.", "es": "Si compras sin conocer tu color personal, desastre de tono asegurado.", "ja": "パーソナルカラーを知らずに買うと百パー トーン崩壊。", "vi": "Mua mà không biết personal color thì chắc chắn lệch tông.", "eng": "Buy without knowing your personal color and it is a guaranteed tone disaster.", "kor": "퍼스널 컬러 모르고 사면 백퍼 톤망진창 됨."}], "definition": "‘톤(tone)’과 ‘엉망진창’을 합친 말로, 자기 피부톤과 어울리지 않아 어색해진 화장이나 의상을 뜻한다. 같은 뜻으로 먼저 쓰이던 ‘톤그로’(톤+aggro)와 겹친다.", "definition_i18n": {"de": "Eine Mischung aus 톤 (Ton) und 엉망진창 (totales Chaos): Make-up oder Kleidung, die mit dem Hautton kollidiert und schief wirkt. Es überschneidet sich mit dem älteren 톤그로 (Ton + Aggro).", "en": "A blend of 톤 (tone) and 엉망진창 (a total mess): makeup or clothing that clashes with your skin tone and ends up looking off. It overlaps with the earlier term 톤그로 (tone + aggro).", "es": "Mezcla de 톤 (tono) y 엉망진창 (un desastre): maquillaje o ropa que choca con tu tono de piel y queda raro. Se solapa con el término anterior 톤그로 (tono + aggro).", "ja": "「トーン(tone)」と「めちゃくちゃ(엉망진창)」を合わせた語で、自分の肌トーンに合わず不自然になったメイクや服装のこと。同じ意味で先に使われていた「톤그로」(トーン+aggro)と重なる。", "vi": "Ghép 톤 (tông màu) với 엉망진창 (be bét): lớp trang điểm hay bộ đồ lệch tông da nên trông kỳ. Nó trùng nghĩa với từ có trước là 톤그로 (tông + aggro)."}}]'::jsonb, '‘톤’과 ‘엉망진창’을 합친 형태로 보이나, 조어 과정을 명시한 출처는 확인되지 않았다. 같은 뜻의 ‘톤그로’(톤+aggro)가 앞서 쓰였고, ‘톤망진창’은 그 자리를 대체하며 2026년 상반기 신조어 정리 기사에 등장했다. 처음 쓰인 시점과 경로는 확인되지 않는다.', '{"de": "Offenbar eine Fusion aus 톤 und 엉망진창, doch keine Quelle erklärt die Bildung. Das gleichbedeutende 톤그로 (Ton + Aggro) kam zuerst, und 톤망진창 taucht als Nachfolger in einem Neologismus-Rückblick zum ersten Halbjahr 2026 auf. Anfang und Weg sind unbelegt.", "en": "It appears to fuse 톤 with 엉망진창, though no source spells out the coinage. The synonymous 톤그로 (tone + aggro) came first, and 톤망진창 shows up in a 2026 first-half slang roundup as its successor. When and where it started is unverified.", "es": "Parece fusionar 톤 con 엉망진창, aunque ninguna fuente explica la formación. El sinónimo 톤그로 (tono + aggro) es anterior, y 톤망진창 aparece como su relevo en un recopilatorio de neologismos del primer semestre de 2026. No se ha verificado cuándo ni cómo empezó.", "ja": "「톤」と「엉망진창」の合成と見られるが、造語過程を明示した出典は確認できない。同義の「톤그로」(トーン+aggro)が先にあり、「톤망진창」はそれを引き継ぐ形で2026年上半期の新語まとめ記事に登場した。初出の時期と経路は未確認。", "vi": "Có vẻ ghép 톤 với 엉망진창, nhưng không nguồn nào nói rõ cách tạo từ. Từ đồng nghĩa 톤그로 (tông + aggro) có trước, và 톤망진창 xuất hiện như bản kế nhiệm trong bài tổng hợp từ mới nửa đầu 2026. Chưa rõ nó bắt đầu khi nào và ra sao."}'::jsonb, '뷰티 후기나 옷 고민 글에서 “톤망진창 됐다”처럼 자조적으로 쓴다. 남의 화장을 두고 쓰면 외모 평가가 되므로 자기 얘기에 쓰는 편이 안전하다.', '{"de": "Selbstironisch in Beauty-Reviews oder Outfit-Posts — „ist ein Ton-Desaster geworden“. Auf fremdes Make-up gemünzt wird es zur Aussehensbewertung, also lieber über sich selbst.", "en": "Used self-deprecatingly in beauty reviews or outfit posts — “it turned into a tone disaster.” Aimed at someone else’s makeup it becomes appearance-policing, so keep it about yourself.", "es": "Se usa con autoironía en reseñas de belleza o dudas de vestuario: “me quedó un desastre de tono”. Dirigido al maquillaje ajeno se convierte en juicio estético, así que mejor sobre una misma.", "ja": "コスメのレビューや服の悩み投稿で「トーン崩壊した」と自虐的に使う。他人のメイクに向けると容姿の品評になるので、自分の話に使う方が安全。", "vi": "Dùng tự trào trong review mỹ phẩm hay bài hỏi phối đồ: “lệch tông hết trơn”. Nhắm vào trang điểm của người khác thì thành soi ngoại hình, nên chỉ nói về mình cho an toàn."}'::jsonb, array['톤그로','꾸안꾸','인생샷'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Tone disaster (clashing makeup/outfit)"}, {"lang": "🇯🇵 JA", "text": "トーン崩壊(似合わないメイク)"}, {"lang": "🇨🇳 ZH", "text": "色调翻车(不搭的妆容)"}, {"lang": "🇻🇳 VI", "text": "Lệch tông tan nát"}, {"lang": "🇪🇸 ES", "text": "Desastre de tono"}, {"lang": "🇩🇪 DE", "text": "Ton-Desaster"}]'::jsonb),
('279', '기카노보', 'Gi-Ka-No-Bo', 'new-slang', '필터·보정 없이 기본 카메라로 찍은 원본 사진', '{"de": "Ein Rohfoto aus der Standardkamera, ohne Filter und Bearbeitung", "en": "A raw photo from the stock camera, no filters or edits", "es": "Foto sin filtros ni retoques, hecha con la cámara nativa", "ja": "フィルターも加工もない、標準カメラで撮った元の写真", "vi": "Ảnh gốc chụp bằng camera mặc định, không filter không chỉnh"}'::jsonb, '[기카노보]', '[{"type": "명사", "examples": [{"de": "Das ist direkt aus der Standardkamera, null bearbeitet, ehrlich.", "es": "Esta es con cámara nativa y sin retocar, en serio no toqué nada.", "ja": "これ標準カメラ・ノー加工。マジで一切いじってない。", "vi": "Ảnh này camera gốc không chỉnh gì luôn, thật đấy.", "eng": "This is straight off the stock camera, zero edits I swear.", "kor": "이거 기카노보임, 진짜 하나도 안 만졌어."}, {"de": "Unbearbeitet so gut? Dann ist heute wohl ein guter Tag haha.", "es": "¿Así sin editar? Hoy vengo con buena cara jaja.", "ja": "ノー加工でこれなら今日は調子いいわw", "vi": "Không chỉnh mà được vầy chắc hôm nay da đẹp haha.", "eng": "Looking like this with no edits at all? Must be a good skin day lol.", "kor": "기카노보로 이 정도면 오늘 컨디션 좋은 듯 ㅋㅋ"}], "definition": "‘기본 카메라 노(no) 보정’의 줄임말. 카메라 앱이나 필터를 쓰지 않고 휴대폰 기본 카메라로 찍어 아무 보정도 하지 않은 사진을 뜻한다. 사진이 꾸밈없이 잘 나왔다는 자신감의 표현으로 붙인다.", "definition_i18n": {"de": "Kurz für „Standardkamera, keine Retusche“: ein Foto, das mit der vorinstallierten Kamera-App aufgenommen und gar nicht bearbeitet wurde. Das Label ist ein kleiner Flex, dass es auch ohne Hilfe gut aussieht.", "en": "Short for “default camera, no retouching”: a photo shot with the phone’s stock camera app and left completely unedited. Tagging a photo this way is a small flex that it looks good with no help.", "es": "Abreviatura de “cámara nativa, sin retoque”: una foto tomada con la app de cámara del móvil y sin editar en absoluto. Etiquetarla así es presumir de que sale bien sin ayuda.", "ja": "「基本カメラ・ノー補正」の略。カメラアプリやフィルターを使わず、スマホの標準カメラで撮ってまったく加工していない写真のこと。盛らなくてもよく撮れた、という自信の表明として付ける。", "vi": "Viết tắt của “camera mặc định, không chỉnh sửa”: ảnh chụp bằng app camera gốc của điện thoại và không hề qua chỉnh. Gắn nhãn này là kiểu khoe nhẹ rằng ảnh đẹp mà chẳng cần photoshop."}}]'::jsonb, '‘기본 카메라’와 영어 no를 쓴 ‘노보정’을 각각 줄여 붙인 말. 2022년 무렵 방송과 SNS에서 이미 통용되고 있었다는 기사 기록이 있으나, 누가 처음 만들었는지는 출처마다 서술이 엇갈려 확정되지 않는다.', '{"de": "Gebildet durch Kürzung von 기본 카메라 (Standardkamera) und 노보정 (keine Retusche). Presseberichte zeigen es bereits 2022 in TV und Social Media, doch die Quellen widersprechen sich bei der Urheberschaft, daher keine Zuschreibung.", "en": "Formed by clipping 기본 카메라 (default camera) and 노보정 (no retouching). Press coverage shows it already circulating on TV and social media by 2022, but sources disagree on who coined it, so no attribution is made.", "es": "Se forma acortando 기본 카메라 (cámara nativa) y 노보정 (sin retoque). La prensa muestra que ya circulaba en televisión y redes hacia 2022, pero las fuentes discrepan sobre quién lo acuñó, así que no se atribuye.", "ja": "「基本カメラ」と「ノー補正」をそれぞれ縮めて繋げた語。2022年ごろにはテレビやSNSで通用していたという記事が残るが、誰が最初に作ったかは出典によって記述が食い違い未確定。", "vi": "Được tạo bằng cách rút gọn 기본 카메라 (camera mặc định) và 노보정 (không chỉnh sửa). Báo chí cho thấy nó đã lưu hành trên truyền hình và mạng xã hội từ khoảng 2022, nhưng các nguồn mâu thuẫn về người đặt ra nên không quy cho ai."}'::jsonb, '인스타그램·스레드에 사진을 올리며 해시태그나 캡션으로 ‘#기카노보’를 붙인다. 보정 사진이 기본값이 된 환경에서 원본임을 강조하는 말이라, 자랑과 인증의 성격을 함께 가진다.', '{"de": "Wird als Hashtag oder Caption unter Fotos auf Instagram oder Threads gesetzt. Wo Bearbeitung Standard ist, wirkt es zugleich als Flex und als Echtheitsnachweis.", "en": "Added as a hashtag or caption when posting photos on Instagram or Threads. In a feed where editing is the default, it both flexes and certifies that the shot is untouched.", "es": "Se añade como hashtag o pie de foto al publicar en Instagram o Threads. En un entorno donde editar es lo normal, sirve a la vez de alarde y de certificado de autenticidad.", "ja": "インスタやThreadsに写真を上げるとき、ハッシュタグやキャプションに「#기카노보」を付ける。加工が当たり前の環境で「元の写真だ」と強調する語なので、自慢と証明の両方の性格を持つ。", "vi": "Thêm làm hashtag hoặc caption khi đăng ảnh lên Instagram, Threads. Trong môi trường chỉnh ảnh là mặc định, nó vừa là khoe vừa là chứng nhận ảnh gốc."}'::jsonb, array['인생샷','꾸안꾸','찐'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "No filter, straight from the camera"}, {"lang": "🇯🇵 JA", "text": "標準カメラ・ノー加工"}, {"lang": "🇨🇳 ZH", "text": "原相机无修图"}, {"lang": "🇻🇳 VI", "text": "Camera gốc, không chỉnh"}, {"lang": "🇪🇸 ES", "text": "Cámara nativa sin filtros"}, {"lang": "🇩🇪 DE", "text": "Originalkamera, unbearbeitet"}]'::jsonb),
('280', '꺄르', 'Kkya-Reu', 'new-slang', '신날 때 내지르는 귀여운 감탄사', '{"de": "Ein niedlicher Freudenquietscher", "en": "A cute squeal of delight", "es": "Un chillido tierno de alegría", "ja": "うれしいときに出すかわいい感嘆詞", "vi": "Tiếng reo dễ thương khi thích thú"}'::jsonb, '[꺄르]', '[{"type": "감탄사", "examples": [{"de": "Ich hab die Konzerttickets, Kkya-reu~", "es": "¡Pillé las entradas del concierto, kkya-reu~!", "ja": "コンサートのチケット取れた、キャル〜", "vi": "Săn được vé concert rồi, kkya-reu~", "eng": "I got the concert tickets, kkya-reu~", "kor": "콘서트 티켓 잡았어 꺄르~"}, {"de": "Morgen fällt die Vorlesung aus, Kkya-reu hahaha.", "es": "Mañana se cancela la clase, kkya-reu jajaja.", "ja": "明日休講だって、キャルwwww", "vi": "Mai nghỉ học nè, kkya-reu haha.", "eng": "Class is cancelled tomorrow, kkya-reu lolol.", "kor": "내일 휴강이래 꺄르 ㅋㅋㅋㅋ"}], "definition": "기분이 좋거나 신날 때 내지르는 감탄사. 놀랄 때 내는 ‘꺅’과 유행 감탄사 ‘야르’가 합쳐진 형태로, ‘야르’보다 한 단계 들뜬 상위 표현으로 쓰인다.", "definition_i18n": {"de": "Ein Ausruf für Aufregung oder Freude. Gebildet aus 꺅 (überraschter Quietscher) plus dem Trendwort 야르, und gilt als eine Stufe ausgelassener als 야르 allein.", "en": "An exclamation for excitement or delight. Formed from 꺅 (a startled squeal) plus the trending 야르, and treated as one notch giddier than 야르 alone.", "es": "Exclamación de emoción o alegría. Nace de 꺅 (chillido de sorpresa) más el 야르 de moda, y se usa como un peldaño más eufórico que 야르.", "ja": "うれしい・楽しいときに出す感嘆詞。驚いたときの「キャッ」と流行の感嘆詞「야르」が合わさった形で、「야르」より一段テンションが高い上位表現として使われる。", "vi": "Thán từ khi phấn khích hay vui sướng. Ghép từ 꺅 (tiếng ré lên vì bất ngờ) với 야르 đang thịnh, được coi là mức phấn khích cao hơn 야르 một bậc."}}]'::jsonb, '여러 설이 있으며 확정되지 않았다. (1) 감탄사 ‘꺅’과 2025~26년 유행한 ‘야르’가 결합했다는 설, (2) 자지러지게 웃는 소리를 뜻하는 기존 의성어 ‘꺄르르’가 짧아진 것이라는 설이 함께 돈다. 어느 쪽이든 ‘야르’·‘샤갈’과 같은 감탄사 밈 계열 안에서 함께 퍼졌다.', '{"de": "Mehrere Versionen, keine gesichert: (1) eine Verschmelzung des Quietschers 꺅 mit dem 2025–26 angesagten 야르; (2) eine Kürzung der bestehenden Lautmalerei 꺄르르 (schallendes Lachen). So oder so verbreitete es sich zusammen mit 야르 und 샤갈 in derselben Ausruf-Meme-Familie.", "en": "Several accounts, none settled: (1) a fusion of the squeal 꺅 with 야르, which trended in 2025–26; (2) a clipping of the existing onomatopoeia 꺄르르 (peals of laughter). Either way it spread alongside 야르 and 샤갈 as part of the same exclamation-meme family.", "es": "Varias versiones, ninguna confirmada: (1) fusión del chillido 꺅 con 야르, de moda en 2025-26; (2) acortamiento de la onomatopeya 꺄르르 (carcajadas). En cualquier caso se difundió junto a 야르 y 샤갈 dentro de la misma familia de memes exclamativos.", "ja": "諸説あり未確定。(1)感嘆詞「キャッ」と2025〜26年に流行した「야르」の合成説、(2)げらげら笑う音を表す既存の擬音語「꺄르르」が短くなった説が併存する。いずれにせよ「야르」「샤갈」と同じ感嘆詞ミーム群の中で広まった。", "vi": "Có vài giả thuyết, chưa cái nào chắc: (1) ghép tiếng ré 꺅 với 야르 thịnh hành 2025–26; (2) rút gọn từ tượng thanh sẵn có 꺄르르 (cười ngặt nghẽo). Dù thế nào nó cũng lan cùng 야르 và 샤갈 trong cùng nhóm meme thán từ."}'::jsonb, '기쁜 소식에 혼잣말·댓글·DM으로 가볍게 붙인다. 애교 섞인 어감이라 격식 있는 자리에서는 쓰지 않는다.', '{"de": "Wird bei guten Nachrichten in Selbstgesprächen, Kommentaren oder DMs angehängt. Es klingt verspielt-niedlich und passt nicht in formelle Situationen.", "en": "Tacked onto good news in self-talk, comments, or DMs. It sounds playful and cutesy, so it does not belong in formal settings.", "es": "Se añade a buenas noticias en comentarios o mensajes. Suena juguetón y mimoso, así que no encaja en contextos formales.", "ja": "うれしい知らせに独り言・コメント・DMで軽く付ける。甘えた響きがあるのでフォーマルな場では使わない。", "vi": "Thêm vào tin vui khi tự nói, bình luận hay nhắn tin. Nghe nũng nịu, dễ thương nên không hợp dịp trang trọng."}'::jsonb, array['야르','할렐야루','샤갈'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Kkya-reu! (eeee! / yay)"}, {"lang": "🇯🇵 JA", "text": "キャル(きゃー!)"}, {"lang": "🇨🇳 ZH", "text": "呀嘞(开心时的尖叫)"}, {"lang": "🇻🇳 VI", "text": "Kkya-reu (a a, thích quá)"}, {"lang": "🇪🇸 ES", "text": "¡Kkya-reu! (¡yupi!)"}, {"lang": "🇩🇪 DE", "text": "Kkya-reu! (Juhu!)"}]'::jsonb),
('281', '할렐야루', 'Hal-Lel-Ya-Ru', 'new-slang', '기쁠 때 외치는 최상급 감탄사', '{"de": "Der Freudenruf der Höchststufe", "en": "A top-tier shout of joy", "es": "El grito de alegría de máximo nivel", "ja": "うれしいときに叫ぶ最上級の感嘆詞", "vi": "Tiếng reo vui ở cấp độ cao nhất"}'::jsonb, '[할렐랴루]', '[{"type": "감탄사", "examples": [{"de": "Ich hab einen freien Tag ans Wochenende drangehängt — Hallel-yaru!", "es": "¡Me dieron un día libre pegado al finde, hallel-yaru!", "ja": "週末に有給までくっついた、ハレルヤル!", "vi": "Cuối tuần được nghỉ thêm một ngày, hallel-yaru!", "eng": "I got a day off attached to the weekend — hallel-yaru!", "kor": "주말에 연차까지 붙었다, 할렐야루!"}, {"de": "Tickets ergattert … echt Hallel-yaru.", "es": "Conseguí las entradas… hallel-yaru de verdad.", "ja": "チケット取れた…マジでハレルヤル", "vi": "Săn được vé rồi… hallel-yaru thật sự.", "eng": "Got the tickets… hallel-yaru for real.", "kor": "티켓팅 성공… 할렐야루 진짜"}], "definition": "아주 기쁘거나 신날 때 외치는 감탄사로, ‘야르’·‘꺄르’보다 더 강한 최상급 표현. ‘대박’, ‘신난다’ 정도의 뜻이며 종교적인 의미로 쓰이지 않는다.", "definition_i18n": {"de": "Ein Ausruf für pure Begeisterung — eine Stufe über 야르 und 꺄르. Bedeutet etwa „Wahnsinn!“ und hat keine religiöse Bedeutung.", "en": "An exclamation for when you are thrilled — a level above 야르 and 꺄르. It means roughly “amazing!” or “yesss!” and carries no religious meaning.", "es": "Exclamación para cuando estás encantado, un nivel por encima de 야르 y 꺄르. Equivale a “¡genial!” o “¡toma ya!”, sin ningún sentido religioso.", "ja": "とてもうれしい・楽しいときに叫ぶ感嘆詞で、「야르」「꺄르」よりも強い最上級表現。「やった」「最高」くらいの意味で、宗教的な意味では使わない。", "vi": "Thán từ khi cực kỳ vui, mạnh hơn 야르 và 꺄르 một bậc. Nghĩa cỡ “đỉnh quá!” hay “tuyệt vời!”, không mang ý nghĩa tôn giáo."}}]'::jsonb, '유래는 여러 설이 있으며 확정되지 않았다. (1) ‘할렐루야’와 유행 감탄사 ‘야르’를 합친 말이라는 설, (2) 한 교회 청년부가 ‘할렐루야’ 팻말의 ‘루’와 ‘야’를 바꿔 들어 ‘할렐야루’가 된 실수가 밈이 됐다는 설이 대표적이다. 어느 쪽이든 2025년 말 무렵부터 퍼졌다는 점은 출처들이 공통으로 말한다.', '{"de": "Die Herkunft ist ungeklärt, mehrere Versionen kursieren. (1) Eine Mischung aus 할렐루야 (Halleluja) und dem Trend-Ausruf 야르. (2) Eine Kirchenjugendgruppe hielt Halleluja-Schilder mit vertauschten Endsilben hoch, und der Patzer wurde zum Meme. Einig sind sich die Quellen nur darin, dass es sich ab Ende 2025 verbreitete.", "en": "The origin is unsettled; several accounts circulate. (1) It is a blend of 할렐루야 (hallelujah) and the trending shout 야르. (2) A church youth group held up hallelujah placards with the last two syllables swapped, and the slip became a meme. Sources agree only that it spread from around late 2025.", "es": "El origen no está fijado y circulan varias versiones. (1) Es una mezcla de 할렐루야 (aleluya) y la exclamación de moda 야르. (2) Un grupo juvenil de una iglesia sostuvo los carteles de aleluya con las dos últimas sílabas invertidas y el desliz se volvió meme. Las fuentes solo coinciden en que se difundió desde finales de 2025.", "ja": "由来には諸説あり未確定。(1)「ハレルヤ」と流行の感嘆詞「야르」の合成という説、(2)ある教会の青年部が「ハレルヤ」のプラカードの「ル」と「ヤ」を入れ替えて持ってしまい、その間違いがミームになったという説が代表的。2025年末ごろから広まった点だけは各出典が一致。", "vi": "Nguồn gốc chưa xác định, có nhiều giả thuyết. (1) Là sự pha trộn giữa 할렐루야 (hallelujah) và thán từ đang thịnh 야르. (2) Nhóm thanh niên một nhà thờ cầm biển hallelujah bị đảo hai âm cuối, và sự nhầm lẫn đó thành meme. Các nguồn chỉ thống nhất rằng nó lan từ khoảng cuối 2025."}'::jsonb, '기쁜 일이 생겼을 때 혼잣말이나 댓글로 외친다. 원말이 종교 어휘라 예배 등 실제 종교적인 자리에서는 쓰지 않는 것이 좋다.', '{"de": "Man ruft es für sich oder schreibt es in Kommentare, wenn etwas Gutes passiert. Da das Ausgangswort religiös ist, meidet man es besser bei Gottesdiensten.", "en": "Shouted to yourself or dropped in comments when something good happens. Since the base word is religious, avoid it in actual worship settings.", "es": "Se grita para uno mismo o se pone en comentarios cuando pasa algo bueno. Como la palabra base es religiosa, conviene evitarla en contextos de culto.", "ja": "うれしいことがあったとき、独り言やコメントで叫ぶ。元が宗教語彙なので、礼拝など実際の宗教の場では使わない方がよい。", "vi": "Reo lên một mình hoặc thả trong bình luận khi có chuyện vui. Vì từ gốc mang tính tôn giáo, nên tránh dùng trong bối cảnh thờ phượng thật."}'::jsonb, array['야르','꺄르','샤갈'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Hallelu-yaru! (yesss!)"}, {"lang": "🇯🇵 JA", "text": "ハレルヤル(最高!)"}, {"lang": "🇨🇳 ZH", "text": "哈利亚路(超开心时的感叹)"}, {"lang": "🇻🇳 VI", "text": "Hallel-yaru (tuyệt vời!)"}, {"lang": "🇪🇸 ES", "text": "¡Hallel-yaru! (¡genial!)"}, {"lang": "🇩🇪 DE", "text": "Hallel-yaru! (Wahnsinn!)"}]'::jsonb);

commit;

